  "Importación de Zotero completada y verificada.": "Zotero のインポートが完了し、検証されました。",
  "Importación cancelada; el catálogo ya importado se conserva.": "インポートはキャンセルされました。インポート済みのカタログは保持されます。",
  "No hay obras con análisis profundo para indexar.": "インデックスに登録するほど深い分析を行った作品はありません。",
  "No hay obras disponibles para indexar.": "インデックスに登録できる作品はありません。",
  "La obra ya no existe.": "その作品はもう存在しません。",
  "No se puede cambiar de bóveda con la cola de análisis activa. Pausa o termina los trabajos pendientes antes de cargar otra bóveda.": "分析キューがアクティブな間はボールトを切り替えることはできません。別のボールトをロードする前に、保留中のジョブを一時停止または終了します。",
  "No se puede cambiar de bóveda mientras se están indexando embeddings de ideas.": "アイデアの埋め込みのインデックス作成中にボールトを切り替えることはできません。",
  "No se puede cambiar de bóveda mientras se están indexando pasajes.": "パッセージのインデックス作成中はボールトを切り替えることはできません。",
  "No se puede cambiar de bóveda mientras se descubren relaciones semánticas.": "セマンティック関係が検出されている間は、ボールトを切り替えることはできません。",
