  "Ruta optimizada por {strategy}: {shown} lecturas priorizadas de {total} obras, agrupadas en fases manejables.": "{strategy} 用に最適化されたパス: {total} からの {shown} 優先読み取りが機能し、管理可能なフェーズにグループ化されます。",
