  "Genera los embeddings que faltan para poder encontrar ideas por significado. No regenera los existentes.": "欠落している埋め込みを生成して、アイデアを意味から見つけられるようにします。既存のものは再生成されません。",
  "Preparar las que falten": "足りないものを用意する",
  "Indexa los fragmentos de texto completo que falten o estén obsoletos, en toda la biblioteca. No requiere análisis de ideas y los ya actuales se omiten.": "ライブラリ全体にわたって、欠落しているか古いフルテキストフラグメントのインデックスを作成します。アイデアの分析は必要なく、既存のアイデアはスキップされます。",
  "Indexar lo que falte": "欠けているものをインデックス化する",
  "Filtros avanzados": "高度なフィルター",
  "Combina condiciones sueltas de la tubería de análisis. Los presets de arriba cubren los casos habituales.": "分析パイプラインの個々の条件を組み合わせます。上記のプリセットは通常のケースをカバーしています。",
  "Ver el detalle paso a paso": "ステップバイステップの詳細を確認する",
