  "Solo abstract": "抄録のみ",
  "Nodus no encontró texto que leer. Añade el PDF o EPUB en Zotero y vuelve a analizar.": "ノダスは読むべきテキストを見つけられませんでした。 Zotero に PDF または EPUB を追加して、再度分析します。",
  "Zotero no está disponible. Ábrelo y vuelve a analizar.": "ゾテロは利用できません。それを開いて再度分析します。",
  "El análisis solo pudo usar el abstract, así que esta obra no tendrá texto citable. Añade el PDF o EPUB en Zotero y vuelve a analizar.": "分析では要約のみを使用できるため、この作品には引用可能なテキストがありません。 Zotero に PDF または EPUB を追加して、再度分析します。",
