  "Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.": "{n} «abstract-only» 作品の再分析がキューに入れられました。キューの進行状況が表示されます。",
  "Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?": "抄録のみで分析された作品を再分析します（分析時には PDF/EPUB は利用できませんでした）。 Zotero でテキストを利用できるようになった人は、完全な分析を復元できるようになります。残りは無料でスキップされます。続く？",
  "Reanalizar": "再分析",
