  "Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.": "ライブラリ全体をスイープし、変更されたインデックスのみを更新します。すでに最新のものはスキップされます。",
  "resumen": "まとめ",
  "solo abstract": "抽象のみ",
