  "Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.": "[設定] → [AI モデル] で有効にできます。レビューは引き続きローカルで機能します。",
  "Modelos de IA": "AIモデル",
  "Modelo general de texto": "一般的なテキストモデル",
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "これらは、Nodus が組み込みモデルの間で除外する重みと同じです。アイデアを抽出するとき、それらはとりとめなく発生し、JSON を決して閉じません。これらを引き続き使用することはできますが、抽出にはより大きなモデルの方が適しています。",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "理由を記録せずにステップが失敗しました。再試行してください。再度失敗する場合は、「設定」→「AI モデル」でモデルを確認してください。",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "まだ選択できるモデルがありません。 [モデルの読み込み] を押してプロバイダーが提供するモデルを表示するか、[設定] → [AI プロバイダーとモデル] で必要なモデルにスターを付けます。",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "{list} からの応答がありません。そのキーを確認するか、ローカルサーバーが実行されていることを確認してください。",
