  "Tus bóvedas actuales no se moverán ni se modificarán. Crearemos una primera copia cifrada y verificada antes de activar la recuperación.": "現在のボールトは移動または変更されません。リカバリを有効にする前に、最初の暗号化されたスナップショットを作成して検証します。",
  "Configura una carpeta segura antes de empezar. Tus bóvedas seguirán trabajando localmente y Nodus guardará aquí copias recuperables.": "開始する前に、安全なフォルダーを構成してください。ボールトはローカルで動作し続け、Nodus は回復可能なスナップショットをここに保存します。",
  "La base de datos activa nunca se abre directamente desde Google Drive o Dropbox: así evitamos conflictos y corrupción.": "ライブデータベースは Google ドライブや Dropbox から直接開かれることはなく、競合や破損を防ぎます。",
