  "Puede ser una carpeta local o una carpeta sincronizada por Google Drive, Dropbox, iCloud u otro servicio. Debe estar vacía.": "ローカルにある場合もあれば、Google Drive、Dropbox、iCloud、または別のサービスによって同期されている場合もあります。空でなければなりません。",
  "Busca la carpeta que contiene nodus-recovery.json y sus copias.": "nodus-recovery.json とそのスナップショットが含まれるフォルダーを選択します。",
  "2. Todo Nodus quedará protegido": "2. Nodus のすべてが保護されます",
  "Sin selecciones ni exclusiones: todas las bóvedas, documentos, preferencias, historiales, medios y claves API se incluirán automáticamente.": "選択や除外はありません。すべてのボールト、ドキュメント、設定、履歴、メディアファイル、および API キーが自動的に含まれます。",
  "2. Elige una copia": "2. スナップショットを選択します",
