  "Número y término": "番号と期間",
  "Objetivo que vale el máximo": "満点としてカウントされる目標",
  "Ojo: con esta opción la nota de un alumno cambia si otro obtiene más.": "注意: このオプションを使用すると、他の生徒の得点が高くなると、生徒の得点が変わります。",
