  "Nota mínima para promediar: {min}": "平均に対する最小マーク: {min}",
  "Pega el apartado de evaluación. La IA propone la estructura; tú la confirmas. Nunca calcula notas.": "評価セクションを貼り付けます。 AI が構造を提案します。あなたはそれを確認します。成績を計算することはありません。",
