  "Análisis de preguntas": "質問分析",
  "Bandas según Baladrón y otros (FEM, 2016) y la guía SEDEM (2014).": "バラドロンらの後のバンド(FEM、2016) および SEDEM ガイド (2014)。",
  "Dificultad: proporción de la puntuación obtenida, así que un valor ALTO significa pregunta FÁCIL. Grupos extremos: {pct} %.": "難易度: 獲得したマークのシェア。したがって、高い値は簡単な問題を意味します。極端なグループ: {pct}%。",
  "Discriminación": "差別",
  "{n} calificaciones · media {mean} · mediana {median} · aprueban {rate} %": "{n} の成績 · 平均 {mean} · 中央値 {median} · 合格率 {rate}",
  "Se eliminarán «{name}», sus {n} elementos internos y todas sus calificaciones. Esta acción no se puede deshacer.": "«{name}»、その {n} 内部項目とそのすべてのグレードが削除されます。これを元に戻すことはできません。",
  "Se eliminará «{name}» y todas sus calificaciones. Esta acción no se puede deshacer.": "«{name}» とそのすべての成績が削除されます。これを元に戻すことはできません。",
