  "Situación de la entrega": "提出状況",
  "Evaluar con la rúbrica": "ルーブリックで評価する",
  "Quedan {n} criterios sin marcar; la nota se calcula solo sobre los evaluados.": "{n} 基準はまだマークされていません。マークは評価されたものに対してのみ計算されます。",
  "Todos los criterios están evaluados.": "あらゆる基準が評価されています。",
  "hasta {n} puntos": "最大 {n} ポイント",
  "Este cuaderno registra la calificación en términos cualitativos, así que la distribución numérica no se aplica.": "この成績表は成績を定性的な用語として記録するため、数値分布は適用されません。",
  "Alumnado con nota en esta pregunta": "この質問にマークが付いている生徒",
