  "Comentario para la familia": "家族へのコメント",
  "La IA solo ve las notas y un identificador, nunca el nombre. Revísalo antes de usarlo.": "AI はマークと識別子のみを認識し、名前は認識しません。使用する前に確認してください。",
  "Lo que se envía": "送信されるもの",
