  "Nueva habilidad": "新しい能力",
  "Editar habilidad": "編集能力",
  "Eliminar habilidad": "削除能力",
  "¿Eliminar esta habilidad?": "この能力を削除しますか?",
  "Sin habilidades registradas.": "能力は記録されていません。",
  "Nombre de la habilidad": "アビリティ名",
  "Qué hace": "何をするのか",
  "Coste": "料金",
  "Qué le cuesta usarla": "それを使用するとどのような費用がかかりますか",
  "Límite": "限界",
  "Qué NO puede hacer con ella": "それを使ってできないこと",
  "El límite es lo que hace interesante a un poder: sin él resuelve cualquier escena.": "限界があるからこそ、パワーが面白くなります。限界がなければ、あらゆるシーンが解決されてしまいます。",
  "Sin límite definido: una habilidad sin límite resuelve cualquier escena.": "制限の設定なし: 制限のない能力はあらゆるシーンを解決します。",
  "Es un secreto": "それは秘密です",
  "Secreto": "秘密",
