  "Quién lo conoce (p. ej. «solo su hermana y el archivero»)": "それを知っているのは誰でしょう (例: 「彼女の妹とアーキビストだけ」)",
  "Los nombres secretos no aparecen en la cuadrícula de personajes.": "シークレット名は文字グリッドには表示されません。",
  "Quitar {name}": "{name} を削除します",
  "Cómo la vive": "彼らがどう感じているか",
  "Solo desde su lado: la otra persona puede vivir la misma relación de forma muy distinta.": "彼らの側からのみ：他の人は同じ絆をまったく異なる方法で生きているかもしれません。",
  "Sin especificar": "不特定",
