  "Neutral": "中性",
  "Muere el año {death}, antes de nacer el año {birth}.": "{birth}年に生まれる前に{death}年に亡くなりました。",
  "Participa en un hecho el año {year}, después de morir el año {death}.": "{death} に死亡した後、{year} 年のイベントに参加します。",
  "Participa en un hecho el año {year}, antes de nacer el año {birth}.": "{birth}年に生まれる前、{year}年にイベントに参加しました。",
  "Tiene fecha de muerte pero su estado sigue siendo «vivo».": "死亡日はありますが、まだ「生存」とマークされています。",
  "Está marcado como muerto pero no consta cuándo.": "死亡したとマークされていますが、いつ死亡したかの記録はありません。",
  "El nombre se parece mucho a «{other}»: quien lea puede confundirlos.": "この名前は「{other}」に非常に近いため、読者はこれらを混同する可能性があります。",
  "Proponer": "プロポーズする",
  "Proponiendo…": "提案…",
  "Propuesta sin aceptar": "受け入れられなかった提案",
  "Aceptar como canon": "正典として受け入れる",
  "Lo que va entre corchetes lo ha inventado la IA. No es canon hasta que lo aceptes.": "括弧内はAIが発明したものです。あなたが受け入れるまでは正典ではありません。",
  "Solo cuenta lo que ya está en la ficha": "すでにシート上にあるもののみを伝えます",
  "Rellena los huecos y marca entre corchetes lo que ha inventado": "発明したものは何でも隙間やブラケットを埋めます",
  "Entrevistar": "インタビュー",
  "Entrevistar a {name}": "インタビュー {name}",
  "Hablar con el personaje en su propia voz": "自分の声でキャラクターに話しかける",
  "Responde en su voz y solo sabe lo que hay en su ficha. Nada de esta conversación se guarda.": "彼らは自分の声で答え、シートに書かれていることだけを知っています。この会話は何も保存されません。",
  "Responde en su propia voz; las conversaciones se guardan en esta bóveda.": "彼らは自分の声で答えます。会話はこの保管庫に保存されます。",
  "Se eliminará «{title}» junto con todos sus mensajes e imágenes. Esta acción no se puede deshacer.": "「{title}」はすべてのメッセージと画像とともに削除されます。この操作は元に戻すことができません。",
  "Pregúntale algo.": "彼らに何か尋ねてください。",
  "Rellena antes su descripción: sin ficha no tiene nada que contestar.": "まず説明を入力します。シートがなければ、何も答えることができません。",
  "Tu pregunta…": "あなたの質問は…",
  "Preguntar": "聞く",
  "«¿De qué te arrepientes?»": "「何を後悔していますか？」",
  "«¿A quién no soportas y por qué?»": "「我慢できないのは誰ですか、そしてその理由は何ですか?」",
  "«¿Qué harías si te quitaran lo que más quieres?»": "「あなたの一番好きなものを奪われたらどうしますか？」",
  "Exportar la ficha a Markdown": "シートをMarkdownにエクスポートする",
  "Ficha guardada en {path}": "シートは {path} に保存されました",
  "(sin los nombres secretos ni tus notas privadas)": "(秘密の名前や個人的なメモは除く)",
  "Plantilla": "テンプレート",
  "Solo el nombre. Rellena la ficha a tu manera.": "名前だけです。独自の方法でシートに記入します。",
  "Héroe a su pesar": "消極的なヒーロー",
  "Alguien a quien la trama saca de su vida sin pedirle permiso. Empieza por qué quería en realidad y qué le impide moverse.": "陰謀のせいで断りもなく人生から引きずり出される人。彼らが実際に望んでいたこと、そして彼らを動かさないものから始めてください。",
  "Tirano con razones": "理由のある暴君",
  "Un antagonista que cree estar salvando algo. Lo importante es la mentira que se cree y de dónde salió.": "自分たちが何かを救っていると信じている敵対者。重要なのは、彼らが信じている嘘と、それがどこから来たのかです。",
  "Mentor con secreto": "秘密を持つメンター",
  "Quien enseña y calla lo que más importa. Define qué protege ocultándolo.": "最も重要なことを教えたり、差し控えたりする人。何を隠すことで何を保護するのかを定義します。",
  "Embaucador": "トリックスター",
  "Quien sobrevive hablando y cambia de bando a tiempo. Su voz es media ficha.": "話すことで生き残り、時間の経過とともに寝返る者。彼らの声はシートの半分です。",
  "Testigo": "目撃者",
  "Un personaje menor que ve lo que nadie más ve. Con poco basta: qué vio y por qué calla.": "他の誰もやらないことを見る脇役。少しで十分です。彼らが何を見たのか、なぜ彼らが沈黙しているのか。",
  "Familias": "家族",
  "Dinastías": "王朝",
  "Calendario del mundo": "世界カレンダー",
  "Definir las eras y los meses de tu mundo": "あなたの世界の時代と月を定義する",
  "Opcional. Sin calendario, el año ordena la cronología igual que hasta ahora; con él, además ordena dentro de cada año y puedes elegir la fecha en vez de escribirla.": "オプション。カレンダーがなければ、年は以前とまったく同じようにタイムラインに順序付けされます。あるものでは、毎年以内に注文することもでき、日付を入力する代わりに日付を選択します。",
  "Nombre del calendario (opcional)": "カレンダー名 (オプション)",
  "Guardar calendario": "カレンダーを保存する",
  "Al guardar se recalculan las fechas de todos los hechos ya registrados.": "保存すると、すでに記録されているすべてのイベントの日付が再計算されます。",
