  "Año inicial": "開始年",
  "El «año inicial» es el año absoluto en el que cae el año 1 de esa era: es lo que permite comparar fechas de eras distintas.": "「開始年」は、元号の1年が該当する絶対的な年です。これにより、異なる時代の日付が比較可能になります。",
  "Cuenta atrás": "カウントダウン",
  "Cuenta hacia atrás, como «a.C.»": "「BC」のように逆算します",
