  "Arquitectura, materiales, colores, cómo se llega…": "建築、素材、色、そこにたどり着くまでの道のり…",
  "Ruidos, olores, quién anda por la calle, qué se teme…": "音、匂い、街に誰がいるのか、何が恐れられているのか…",
  "Fundación, guerras, quién lo gobernó…": "建国、戦争、誰が統治したか…",
  "Lo que se añade a todas las imágenes para que el lugar se parezca a sí mismo.": "すべての画像に追加すると、その場所自体が見えるようになります。",
  "p. ej. «ciudad portuaria de piedra gris, tejados de pizarra, niebla»": "例えば「灰色の石造りの港町、スレート屋根、霧」",
  "Quién está aquí": "ここには誰がいますか",
  "Nadie por ahora. Se añaden desde la ficha del personaje, en sus lugares.": "まだ誰もいません。これらはキャラクターのシートから所定の位置に追加されます。",
  "Un lugar de tipo «{child}» está dentro de uno de tipo «{parent}». ¿Es a propósito?": "「{child}」は「{parent}」の中にあります。それは故意ですか？",
  "¿Eliminar este lugar? Los lugares que contiene NO se borran: pasan a estar sueltos.": "この場所を削除しますか?その中の場所は削除されず、配置されなくなります。",
  "¿Eliminar esta imagen de la galería?": "この画像をギャラリーから削除しますか?",
  "Escribe primero la apariencia en la sección Descripción.": "まず説明セクションに外観を書きます。",
