  "Sucesión, ramas, reclamaciones, lemas y legitimidad.": "継承、枝分かれ、主張、モットー、そして正当性。",
  "Herederos, ramas cadetes, disputas sucesorias…": "相続人、士官候補生の分家、後継者争い…。",
  "Miembros": "メンバー",
  "Miembro": "メンバー",
  "Pertenencias": "メンバーシップ",
  "Añadir pertenencia": "メンバーシップを追加する",
  "No pertenece a nada por ahora.": "まだ何にも属していません。",
  "Crea antes una facción, una cultura o una dinastía.": "まず派閥、文化、または王朝を作成します。",
  "Nadie por ahora. Se añaden desde la ficha del personaje, en sus pertenencias.": "まだ誰もいません。これらは、キャラクターのシートのメンバーシップの下に追加されます。",
  "En una línea": "一行で",
  "Lo que dirías de esto en una frase.": "それについて一言で言うと何でしょう。",
  "Lo que se ve: emblemas, colores, vestimenta, arquitectura.": "目に見えるもの：エンブレム、色、ドレス、建築。",
  "Símbolos, atuendo, cómo se reconoce a los suyos…": "シンボル、服装、それ自体がどのように認識されるか…",
  "Lo que se añade a todas las imágenes para que se parezcan entre sí.": "すべての画像に追加すると、見た目が似てきます。",
  "p. ej. «heráldica de cuervo negro sobre campo gris, plata bruñida»": "例えば「灰色の野原に黒いカラスの紋章、磨かれた銀」",
  "p. ej. «los espías de la corte, que ya no responden ante nadie»": "例えば「もう誰にも答えない宮廷のスパイ」",
  "{from} → {to}": "{from} → {to}",
  "¿Eliminar esto? Los personajes NO se borran: solo dejan de pertenecer.": "これを削除しますか?キャラクターは削除されません。単に属さなくなるだけです。",
  "Nueva escena": "新しいシーン",
  "Crear escena": "シーンの作成",
  "Eliminar escena": "シーンの削除",
  "Buscar escenas…": "シーンを検索…",
  "Título de la escena": "シーンのタイトル",
  "Volver a las escenas": "シーンに戻る",
  "Todavía no hay escenas en este mundo.": "この世界にはまだシーンがありません。",
  "Ninguna escena coincide con el filtro.": "フィルターに一致するシーンはありません。",
  "Se añade al final del relato; puedes moverla después.": "それは話の最後に追加されます。後で移動することもできます。",
  "Esbozo": "概要",
  "Escrita": "書かれた",
  "Orden en el relato": "告げる順序",
  "Sin lugar": "場所がない",
  "Qué pasa": "何が起こるのですか",
  "Lo que ocurre en la escena, en tus palabras.": "現場で起こったことをあなた自身の言葉で。",
  "Quién quiere qué, quién se lo impide y cómo acaba…": "誰が何を望み、誰がそれを止め、そしてどのように終わるのか…",
  "Quién aparece": "誰が登場するのか",
  "Añadir personaje a la escena": "シーンにキャラクターを追加する",
  "Crea antes algún personaje.": "まずはキャラクターを作成します。",
  "¿Eliminar esta escena? Los personajes que aparecen en ella NO se borran.": "このシーンを削除しますか?登場するキャラクターは削除されません。",
  "El año es cuándo ocurre en el mundo; el orden es dónde va en el relato. Un prólogo ambientado siglos antes va primero en el relato y último en la cronología.": "今年は世界でそれが起こる年です。順序はそれが物語の中でどこに位置するかです。何世紀も前に設定されたプロローグは、物語の最初にあり、年表では最後にあります。",
  "Apariciones": "出演",
  "En orden del relato, no de la cronología.": "年表ではなく、物語の順序で。",
  "Secretos": "秘密",
  "Añadir secreto": "シークレットを追加",
  "Qué esconde…": "彼らが隠しているものは…",
  "No esconde nada por ahora.": "まだ何も隠していません。",
  "Revelado": "明らかにした",
  "Además sabe": "も知っています",
  "Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.": "常にソースに基づいて、教師向けの単元や生徒向けの配布物をデザインします。",
  "Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.": "レッスンを指導するための計画が必要か、それともすぐに共有できるメモが必要かを選択します。",
  "Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.": "学習のためのメモが必要か、トピックを教えるための計画が必要かを選択してください。",
  "Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.": "準備したいトピックまたはレッスンを入力します。レポートでは、資料に基づいて目的、順序、活動、評価を設計します。",
  "Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.": "メモのトピックを入力します。レポートでは、資料から抽出された例と自己評価を使用して、それを段階的に説明します。",
  "Público objetivo y producto": "対象読者と成果物",
  "Docente · planificación de la lección": "先生・レッスンプラン",
  "Alumnado · apuntes para entregar": "学生 · すぐに共有できるメモ",
  "Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.": "それは、教師の目的、順序、活動、理解度のチェック、および評価を生成します。",
  "Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.": "学生向けの説明、定義、例、要約、自己評価が生成されます。",
  "En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.": "「作成」で、教育単元が教材から教師計画や生徒のメモを生成できるようになりました。残りの点線のセクションは、引き続きご提案をお待ちしております。このチュートリアルは [設定] から再実行できます。",
  "Artefacto": "アーチファクト",
  "Costumbre": "カスタム",
  "Criatura": "生き物",
  "Cuerpo": "体",
  "Escena": "シーン",
  "Facción o cultura": "派閥とか文化とか",
  "Fauna": "動物相",
  "Flora": "フローラ",
  "Personaje": "キャラクター",
  "Sistema de magia": "魔法システム",
  "Suceso": "イベント",
  "Tecnología": "テクノロジー",
  "Esta entrada todavía no existe": "このエントリはまだ存在しません",
  "Crear la entrada «{name}»": "エントリ「{name}」を作成します",
  "Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.": "記事は、キャラクター、場所、派閥以外のもの、つまり魔法、宗教、言語、生き物、物体を対象としています。それ以外のものはすべて、すでに百科事典に単独で載っています。",
  "Nuevo artículo": "新しい記事",
  "Todavía nadie ha definido esto. Al crearlo, todas las menciones que lo esperaban quedarán enlazadas.": "まだ誰もこれを定義していません。これを作成すると、それを待っていたすべてのメンションがリンクされます。",
  "Escribe [[ para enlazar con cualquier cosa del mundo": "[[ と入力して世界中のあらゆるものにリンクします",
  "Escribe la entrada…": "エントリーを書いて…",
