  "Esta ficha aún no tiene texto. Se escribe en su propia sección.": "このシートにはまだテキストがありません。それは独自のセクションに書かれています。",
  "Ficha completa": "フルシート",
  "Las menciones que la enlazaban no se borran: quedarán marcadas como pendientes.": "リンクされているメンションは削除されず、保留中としてマークされます。",
  "Mencionada en": "で言及",
