  "reglas del mundo, conflictos, arcos narrativos, consistencia, preguntas abiertas, tramas y manuscritos": "世界ルール、紛争、ストーリーアーク、一貫性、未解決の質問、プロットと原稿",
  "En la enciclopedia": "百科事典では",
  "{count} sin desarrollar": "{count} 未開発",
  "Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].": "キャラクター、場所、派閥、文化、シーン、マップなど、架空の世界を少しずつ構築していきます。百科事典はそれらすべてを1つの索引に集め、世界の残りの部分 (魔法、宗教、言語) を [[二重括弧]] でリンクして書くことができます。",
  "Analizar el mundo": "世界を分析する",
  "Aparecen a menudo y no están definidos": "それらは頻繁に登場しますが、定義されていません",
  "Esto es una sospecha, no un hecho: son nombres que se repiten en tus textos.": "これは直感であり、事実ではありません。これらの名前はテキスト内で繰り返し出てきます。",
  "Lo escribiste tú entre dobles corchetes, así que ya existen en tu mundo.": "これらは二重括弧内に自分で書いたものなので、すでにあなたの世界に存在しています。",
