  "Preguntar a Nodi sobre la selección": "ノディに選択について尋ねる",
  "Copiar dirección": "アドレスをコピーする",
  "Abrir en el navegador del sistema": "システムブラウザで開く",
  "Esta página no ofrece nada que se pueda guardar.": "このページには保存できるものは何もありません。",
  "Nodi ya tiene esta página como contexto.": "Nodi はこのページをコンテキストとして持つようになりました。",
  "Nodi ya tiene la selección.": "これで Nodi が選択できるようになりました。",
  "No había nada que enviar.": "送るものは何もありませんでした。",
  "Guardado en la Biblioteca: {title}": "ライブラリに保存されました: {title}",
  "Solo se pueden guardar páginas web HTTP o HTTPS.": "ブックマークできるのは、HTTP または HTTPS Web ページのみです。",
  "Esta página ya está guardada en Nodus Bookmarks.": "このページはすでに Nodus ブックマークに保存されています。",
