  "Preguntar dónde guardar cada archivo": "各ファイルの保存場所を尋ねる",
  "¿Borrar los datos seleccionados?": "選択したデータを削除しますか?",
  "¿Borrar todos los datos de navegación?": "閲覧データをすべて消去しますか?",
  "Borrar las cookies cerrará tu sesión en los sitios donde la tengas iniciada.": "Cookie を削除すると、サインインしているサイトからサインアウトされます。",
  "También se cerrarán todas las pestañas abiertas del navegador.": "開いているブラウザのタブもすべて閉じられます。",
  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium は登録可能なドメインごとに Cookie をクリアします。サブドメインの Cookie をクリアすると、メインドメインとその他のサブドメインの Cookie もクリアされます。",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus はキャッシュとプロファイルの合計サイズを測定できます。 Chromium は各ストレージカテゴリのサイズを個別に報告しないため、残りは影響を受けるサイトの数で表示されます。",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser は Cookie とサイトストレージを保持するため、必要に応じてサインインした状態を維持できます。 Nodus にはユーザー名やパスワードは保存されず、パスワードマネージャーも含まれません。",
