  "Excepción: los marcados no registran ningún autor, así que sus ideas se muestran aquí de forma provisional.": "例外: マークが付いているものには著者がまったく記録されていないため、ここでは彼らのアイデアを暫定的に示します。",
  "Esta obra no registra ningún autor: sus ideas se atribuyen provisionalmente a quien la edita": "この作品には作者が記録されていません。そのアイデアは暫定的に編集者のものとされています",
