  "Conecta Nodus con cualquier servidor que hable la API de OpenAI: LiteLLM, vLLM, el servidor de llama.cpp o un proxy propio.": "Nodus を OpenAI API を使用する任意のサーバー (LiteLLM、vLLM、llama.cpp サーバー、または独自のプロキシ) に接続します。",
