  "Modelos escritos a mano": "手入力モデル",
  "Si tu servidor no publica catálogo, escribe aquí los identificadores. Quedan guardados y se pueden elegir en cualquier selector de modelo.": "サーバーがカタログを公開していない場合は、ここに識別子を入力します。これらは保存され、任意のモデルセレクターで選択できます。",
