  "Este proveedor genera texto, no embeddings. Para la búsqueda semántica elige otro proveedor en Ajustes.": "このプロバイダーは、埋め込みではなくテキストを生成します。セマンティック検索の場合は、[設定] で別のプロバイダーを選択します。",
  "Instalar y reiniciar": "インストールして再起動する",
