  "Palabras por sección, no del informe entero. Es una orientación: si la evidencia se agota antes, la sección termina antes en lugar de repetirse o rellenar.": "レポート全体ではなく、セクションごとの単語。これはガイダンスです。証拠が先になくなった場合は、そのセクションを繰り返したりパディングしたりせずに、早めに終了します。",
  "Corrige la extensión orientativa de cada sección antes de generar el informe.": "レポートを生成する前に、各セクションのガイドラインの長さを修正します。",
